<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useFitness, asset } from './store'
import { clone, type Exercise } from '../../../shared/fitness'
import { confirmDelete } from '../lib/api'
const fs=useFitness(), query=ref(''),part=ref('全部'),equipment=ref('全部'),favorites=ref(false),page=ref(1),draft=ref<Exercise>(clone(fs.exercises[0])),imageIndex=ref(0)
const parts=['全部','胸','背','肩','腿','臀','手臂','核心','有氧','颈'],equipments=['全部',...new Set(fs.exercises.map(e=>e.equipment))]
const filtered=computed(()=>fs.exercises.filter(e=>(part.value==='全部'||e.part===part.value)&&(equipment.value==='全部'||e.equipment===equipment.value)&&(!favorites.value||e.favorite)&&(e.name+e.alias+e.description+e.tags.join(' ')).toLowerCase().includes(query.value.toLowerCase())))
const visible=computed(()=>filtered.value.slice((page.value-1)*6,page.value*6))
watch([query,part,equipment,favorites],()=>page.value=1)
function select(e:Exercise):void {draft.value=clone(e);imageIndex.value=0}
async function favorite(e:Exercise):Promise<void>{const v=clone(e);v.favorite=!v.favorite;fs.editExercise(v);if(draft.value.id===e.id)draft.value.favorite=v.favorite;await fs.save()}
function create():void{draft.value={id:crypto.randomUUID(),name:'新动作',alias:'',part:'自定义',muscles:[],secondary:[],equipment:'自重',measure:'weight',description:'',notes:'',image:'',images:[],favorite:false,tags:[]}}
async function save():Promise<void>{if(!draft.value.name.trim())return;draft.value.description='主要锻炼'+draft.value.muscles.join('、')+'。'+(draft.value.secondary.length?'辅助参与：'+draft.value.secondary.join('、')+'。':'');fs.editExercise(draft.value);await fs.save('动作已保存')}
function upload(event:Event):void{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{draft.value.image=String(reader.result);draft.value.images=[draft.value.image];imageIndex.value=0};reader.readAsDataURL(file)}
async function remove():Promise<void>{if(!await confirmDelete(draft.value.name))return;fs.data.exercises=fs.data.exercises.filter(e=>e.id!==draft.value.id);await fs.save();select(fs.exercises[0])}
const isCustom=computed(()=>!fs.exercises.some(e=>e.id===draft.value.id&&e.alias))
const linked=computed(()=>fs.data.templates.filter(t=>t.items.some(i=>i.exerciseId===draft.value.id)))
</script>
<template>
 <div class="fit-library-tools fit-card"><input v-model="query" placeholder="⌕ 搜索动作名称、英文名、肌肉或标签"/><div class="fit-filter-chips"><span>部位：</span><button v-for="p in parts" :class="{active:part===p}" @click="part=p">{{ p }}</button></div><div class="fit-filter-chips"><span>器械：</span><select v-model="equipment"><option v-for="e in equipments">{{ e }}</option></select><button :class="{active:favorites}" @click="favorites=!favorites">☆ 收藏</button><button class="fit-primary" @click="create">＋ 新建动作</button></div></div>
 <div class="fit-library-columns"><div><div class="fit-exercise-grid"><button class="fit-exercise-card fit-card" :class="{selected:draft.id===e.id}" v-for="e in visible" :key="e.id" @click="select(e)"><div class="fit-exercise-picture"><img v-if="e.image" :src="asset(e.image)" loading="lazy" :alt="e.name"/><span v-else>♧</span></div><div><header><h3>{{ e.name }}</h3><span role="button" tabindex="0" class="fit-favorite" :class="{on:e.favorite}" @click.stop="favorite(e)" @keydown.enter.stop="favorite(e)">{{ e.favorite?'★':'☆' }}</span></header><div class="fit-tags"><span>{{ e.part }}</span><span>{{ e.equipment }}</span></div><p>{{ e.description }}</p><small>{{ e.measure==='weight'?'次数 × 重量':e.measure==='time'?'时长':'距离' }}</small></div></button></div><p v-if="!visible.length" class="fit-empty fit-card">没有匹配动作，试试其他部位或关键词。</p><div class="fit-pagination"><span>共 {{ filtered.length }} 个动作 · 离线动作库</span><button @click="page=Math.max(1,page-1)" :disabled="page===1">‹</button><strong>{{ page }} / {{ Math.max(1,Math.ceil(filtered.length/6)) }}</strong><button @click="page++" :disabled="page*6>=filtered.length">›</button></div><p class="fit-muted">资料与示范图：Free Exercise DB · Unlicense。少量壶铃动作使用器械示意图。</p></div>
 <section class="fit-card fit-exercise-detail"><header><h2>♧ 动作详情</h2><button class="fit-text" @click="favorite(draft)">{{ draft.favorite?'★ 已收藏':'☆ 收藏' }}</button></header><div class="fit-detail-image"><img v-if="draft.images[imageIndex]||draft.image" :src="asset(draft.images[imageIndex]||draft.image)" :alt="draft.name"/><div v-if="draft.images.length>1" class="fit-segment"><button v-for="(_,i) in draft.images" :class="{active:imageIndex===i}" @click="imageIndex=i">示范 {{ i+1 }}</button></div></div><div class="fit-form-grid"><label>动作名称<input v-model="draft.name"/></label><label>英文名 / 别名<input v-model="draft.alias"/></label><label>部位<select v-model="draft.part"><option v-for="p in [...parts.slice(1),'自定义']">{{ p }}</option></select></label><label>器械<select v-model="draft.equipment"><option v-for="e in equipments.slice(1)">{{ e }}</option></select></label></div><label class="fit-label">主要肌肉<input :value="draft.muscles.join('、')" @input="draft.muscles=($event.target as HTMLInputElement).value.split('、')" placeholder="如：背阔肌、菱形肌"/></label><label class="fit-label">辅助肌肉<input :value="draft.secondary.join('、')" @input="draft.secondary=($event.target as HTMLInputElement).value.split('、').filter(Boolean)"/></label><label class="fit-label">计量方式<select v-model="draft.measure"><option value="weight">次数 × 重量</option><option value="time">时长（秒）</option><option value="distance">距离（米）</option></select></label><label class="fit-label">自定义标签<input :value="draft.tags.join('、')" @input="draft.tags=($event.target as HTMLInputElement).value.split('、').filter(Boolean)"/></label><label class="fit-label">我的动作笔记<textarea v-model="draft.notes" placeholder="记录适合自己的动作细节"/></label><label class="fit-upload">＋ 上传自定义配图<input type="file" accept="image/*" @change="upload"/></label><p class="fit-note">已用于 {{ linked.length }} 个模板：{{ linked.map(t=>t.title).join('、')||'暂无' }}</p><div class="fit-actions"><button class="fit-primary" @click="save">保存动作</button><button v-if="isCustom" class="fit-text" @click="remove">删除自定义动作</button></div></section>
 </div>
</template>
